const cmds = $input.first().json.xjx?.cmd || [];
const employeeData = {};
const dependentesMap = {};
const beneficiosMap = {};

for (const cmd of cmds) {
  // Verifica se é uma atribuição de variável (n="as" e p="value")
  if (cmd.n === 'as' && cmd.p === 'value' && cmd.t) {
    const fieldName = cmd.t;
    const fieldValue = cmd._ || ''; // Se a tag for vazia, o n8n não cria o '_', então assumimos ''

    // Verifica se a chave termina com underscore e número (ex: _1, _2)
    const match = fieldName.match(/_([0-9]+)$/);

    if (match) {
      const num = match[1];
      const baseKey = fieldName.replace(/_[0-9]+$/, '');

      if (fieldName.includes('dependente')) {
        if (!dependentesMap[num]) dependentesMap[num] = {};
        dependentesMap[num][baseKey] = fieldValue;
      } else if (fieldName.includes('beneficio')) {
        if (!beneficiosMap[num]) beneficiosMap[num] = {};
        beneficiosMap[num][baseKey] = fieldValue;
      } else {
        // Se for numerado mas não for dependente/beneficio, vai pro global
        employeeData[fieldName] = fieldValue;
      }
    } else {
      // Dados normais do funcionário
      employeeData[fieldName] = fieldValue;
    }
  }
}

return {
  employeeData: employeeData,
  dependentes: Object.values(dependentesMap),
  beneficios: Object.values(beneficiosMap)
};
